// Ajuste aqui a janela de busca (em dias) a partir de hoje.
const diasParaTras = 3;

const hoje = new Date();
const inicio = new Date();
inicio.setDate(hoje.getDate() - diasParaTras);

return [
  {
    json: {
      startDateStr: inicio.toISOString().slice(0, 10),
      endDateStr: hoje.toISOString().slice(0, 10),
    },
  },
];

// Replica server/src/services/pncpFetcher.js: busca paginada na API do PNCP,
// mapeia os campos para o formato da tabela licitacoes_pncp e remove
// duplicados de id_compra dentro de cada página (necessário para o upsert).

const PNCP_API = 'https://dadosabertos.compras.gov.br/modulo-contratacoes/1_consultarContratacoes_PNCP_14133';
const TAMANHO_PAGINA = 500;
const MODALIDADE_PREGAO_ELETRONICO = 5;

const { startDateStr, endDateStr } = $input.first().json;

async function buscarPagina(pagina) {
  const tentativasMax = 3;
  for (let tentativa = 1; tentativa <= tentativasMax; tentativa++) {
    try {
      return await this.helpers.httpRequest({
        method: 'GET',
        url: PNCP_API,
        qs: {
          pagina: String(pagina),
          tamanhoPagina: String(TAMANHO_PAGINA),
          codigoModalidade: String(MODALIDADE_PREGAO_ELETRONICO),
          dataPublicacaoPncpInicial: startDateStr,
          dataPublicacaoPncpFinal: endDateStr,
        },
        headers: { Accept: 'application/json' },
        json: true,
      });
    } catch (erro) {
      if (tentativa === tentativasMax) throw erro;
      await new Promise((resolve) => setTimeout(resolve, 1000 * tentativa));
    }
  }
}

const paginasDeSaida = [];
let pagina = 1;
let temMais = true;

while (temMais) {
  const dados = await buscarPagina.call(this, pagina);
  const resultados = dados.resultado || [];

  if (resultados.length === 0) break;

  const batch = resultados.map((item) => ({
    id_compra: item.idCompra,
    uasg: item.unidadeOrgaoCodigoUnidade,
    unidade: item.unidadeOrgaoNomeUnidade,
    orgao: item.orgaoEntidadeRazaoSocial,
    uf: item.unidadeOrgaoUfSigla,
    municipio: item.unidadeOrgaoMunicipioNome,
    numero_pregao: item.numeroCompra,
    ano_pregao: item.anoCompraPncp,
    modalidade: item.modalidadeNome,
    objeto: item.objetoCompra,
    situacao: item.situacaoCompraNomePncp,
    valor_estimado: item.valorTotalEstimado,
    data_abertura: item.dataAberturaPropostaPncp,
    data_encerramento: item.dataEncerramentoPropostaPncp,
    link: `https://cnetmobile.estaleiro.serpro.gov.br/comprasnet-web/public/compras/acompanhamento-compra?compra=${item.idCompra}`,
    dados_completos: item,
    atualizado_em: new Date().toISOString(),
  }));

  // Evita o erro do Postgres "ON CONFLICT DO UPDATE command cannot affect row a second time"
  const seenIds = new Set();
  const uniqueBatch = batch.filter((item) => {
    if (!item.id_compra || seenIds.has(item.id_compra)) return false;
    seenIds.add(item.id_compra);
    return true;
  });

  paginasDeSaida.push({
    json: {
      pagina,
      totalRegistrosPagina: uniqueBatch.length,
      registros: uniqueBatch,
    },
  });

  const totalPaginas = dados.totalPaginas || 1;
  temMais = pagina < totalPaginas;
  pagina++;
}

return paginasDeSaida;

const paginas = $('Buscar Licitações no PNCP (paginado)').all();
const totalRegistros = paginas.reduce((soma, item) => soma + (item.json.totalRegistrosPagina || 0), 0);

return [
  {
    json: {
      executadoEm: new Date().toISOString(),
      totalPaginasProcessadas: paginas.length,
      totalRegistrosEnviados: totalRegistros,
    },
  },
];
